// Simulating the underlying route-matching idea with plain, runnable JS --
// folders (keys) map to handlers, and a bracketed segment is a wildcard
const routes = {
  "/": () => "Home page",
  "/blog": () => "Blog index",
  "/blog/:slug": (params) => `Blog post: ${params.slug}`,
};

function matchRoute(path) {
  if (routes[path]) return routes[path]();
  const [, base, slug] = path.match(/^\/(blog)\/(.+)$/) || [];
  if (base === "blog") return routes["/blog/:slug"]({ slug });
  return "404 Not Found";
}

