// Simulating the 'stale cache until explicitly revalidated' idea -- plain, runnable JS
const db = ["Hello World"];         // the REAL, persistent data store
const cache = new Map();             // a separate cache layer sitting in front of it

function getCachedPosts() {
  if (!cache.has("/posts")) {
    cache.set("/posts", [...db]);     // pretend this was an expensive fetch from the db
    console.log("[cache miss] fetched fresh posts");
  } else {
    console.log("[cache hit] served stale/cached posts");
  }
  return cache.get("/posts");
}

function createPostAndRevalidate(newTitle, shouldRevalidate) {
  db.push(newTitle);                  // the mutation writes to the real data store
  if (shouldRevalidate) {
    cache.delete("/posts");            // simulating revalidatePath -- forces a fresh fetch next time
  }
}

console.log(getCachedPosts());                          // cache miss, fetches ["Hello World"]
createPostAndRevalidate("Second Post", false);            // mutate WITHOUT revalidating
console.log(getCachedPosts());                           // cache hit -- stale, missing "Second Post"!
createPostAndRevalidate("Third Post", true);              // mutate WITH revalidation
console.log(getCachedPosts());                           // cache miss -- fresh, includes everything

