// Simulating why session revocation is instant but JWT revocation is NOT,
// with plain, runnable JS standing in for both models
const serverSessions = new Map();   // session-based: server holds the source of truth

function loginSession(userId) {
  const sessionId = "sess_" + Math.random().toString(36).slice(2);
  serverSessions.set(sessionId, { userId, valid: true });
  return sessionId;
}
function logoutSession(sessionId) {
  serverSessions.delete(sessionId);   // instantly invalidated -- server just forgets it
}
function checkSession(sessionId) {
  return serverSessions.has(sessionId);
}

const sid = loginSession("aditi");
console.log("session valid before logout:", checkSession(sid));
logoutSession(sid);
console.log("session valid after logout:", checkSession(sid));   // false -- instant

// A JWT, by contrast, has no server-side record to delete --
// it remains verifiably 'valid' (signature checks out) until its own expiry time passes,
// regardless of any 'logout' the client-side UI performs

import crypto from "node:crypto";

function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString("hex");   // unique per user, never reused
  const hash = crypto.scryptSync(password, salt, 64).toString("hex");
  return `${salt}:${hash}`;    // store BOTH -- salt isn't secret, it just must be unique
}

function verifyPassword(password, stored) {
  const [salt, originalHash] = stored.split(":");
  const hash = crypto.scryptSync(password, salt, 64).toString("hex");
  return crypto.timingSafeEqual(Buffer.from(hash, "hex"), Buffer.from(originalHash, "hex"));
}

const stored = hashPassword("correct-horse-battery-staple");
console.log("Correct password verifies:", verifyPassword("correct-horse-battery-staple", stored));
console.log("Wrong password verifies:", verifyPassword("wrong-password", stored));

const stored2 = hashPassword("correct-horse-battery-staple");
console.log("Two hashes of the SAME password differ:", stored !== stored2);

// (Conceptual walkthrough of the OAuth "authorization code" flow --
// not a single runnable script, since it requires a real registered
// OAuth app and a real browser redirect round-trip)

const flow = `
1. User clicks "Sign in with Google" on YOUR app
2. YOUR app redirects the browser to Google's own login/consent page
3. User logs in and approves access ON GOOGLE'S SITE -- never on your app
4. Google redirects back to YOUR app with a one-time authorization CODE
5. YOUR BACKEND exchanges that code (plus a secret only your backend holds)
   for an access token, via a direct server-to-server request to Google
6. YOUR app now has a token proving the user's identity/granted permissions,
   without ever having seen the user's actual Google password
`;
