// Simulating the difference between 'UI hides the button' (NOT real authorization)
// and 'the action itself checks' (REAL authorization) -- plain, runnable JS
function deletePost_UIOnlyCheck(postId, currentUser, isAdminAccordingToUI) {
  // BAD: trusts a flag the CALLER provides, doesn't independently verify anything
  if (!isAdminAccordingToUI) throw new Error("not allowed");
  return `post ${postId} deleted by ${currentUser}`;
}

const realAdmins = new Set(["aditi"]);
function deletePost_RealCheck(postId, currentUser) {
  // GOOD: independently verifies against a real source of truth, every single call
  if (!realAdmins.has(currentUser)) throw new Error("not allowed");
  return `post ${postId} deleted by ${currentUser}`;
}

// An attacker who can call the function directly (bypassing the real UI)
// can simply CLAIM isAdminAccordingToUI = true -- the first version trusts this blindly
console.log(deletePost_UIOnlyCheck(1, "attacker", true));   // succeeds -- BAD
try {
  deletePost_RealCheck(1, "attacker");                        // correctly rejected
} catch (e) {
  console.log("Correctly rejected:", e.message);
}

// SQL injection: user input spliced directly into a query STRING
function buildUnsafeQuery(username) {
  return `SELECT * FROM users WHERE username = '${username}'`;
}

console.log("Normal input:", buildUnsafeQuery("aditi"));

const maliciousInput = "' OR '1'='1";
console.log("Malicious input:", buildUnsafeQuery(maliciousInput));
// Resulting WHERE clause: WHERE username = '' OR '1'='1' -- always true, matches EVERY row

// The fix: a PARAMETERIZED query -- text and data travel separately
function buildSafeQuery(username) {
  return { text: "SELECT * FROM users WHERE username = $1", values: [username] };
}
console.log("Safe, parameterized:", buildSafeQuery(maliciousInput));
// The malicious string is passed as a plain DATA VALUE for $1 --
// the database never interprets it as SQL syntax at all

// XSS: rendering untrusted content directly as HTML vs. as plain text
const userComment = '<img src=x onerror="alert(\'hacked\')">';

// UNSAFE (conceptual): directly inserting into innerHTML would EXECUTE that script
// element.innerHTML = userComment;   // the onerror handler would actually run

// SAFE: treating it as plain TEXT content, never parsed as HTML/executable markup
function escapeForDisplay(text) {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}
console.log("Raw (dangerous if rendered as HTML):", userComment);
console.log("Escaped (safe to render):", escapeForDisplay(userComment));
// React (this path's own React module) does exactly this kind of escaping
// AUTOMATICALLY for any text content rendered inside JSX, e.g. {userComment}

